"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3543],{20963:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JumpTransitionController","desc":"Renders the jump transition: the wormhole growing ahead of the train, the\\nlightspeed rig, and a post-processing wash \u2014 plus the one-shot and looped SFX.\\n\\nThis is **not** a cutscene. Nothing here takes camera or movement control; the\\nplayer keeps playing while the world changes around them.\\n\\nLighting is captured before anything is applied and restored through the jump\\nJanitor, so a disconnect, an error, or a phase packet arriving out of order\\ncan never leave a player\'s Lighting permanently altered. That restoration is\\nthe one part of this controller where failure is not merely cosmetic.","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/JumpTransitionController.client.luau"}}')}}]);